async function runEntry(entry){if(busy)return;$('#error').hidden=true;setBusy(true);try{const r=await executeSQL(entry.sql);render(r,entry);view('explore');}catch(e){failure(e);}finally{setBusy(false);}}
function matchSample(question){const q=question.trim().toLowerCase().replace(/[?!.]+$/,'');return catalog.find(e=>[e.title,e.description].some(t=>t.toLowerCase().replace(/[?!.]+$/,'')===q));}
async function ask(question){if(busy)return;if(!question.trim()){toast('Enter a question or choose a sample below.');return;}const entry=matchSample(question);if(entry){await runEntry({...entry,title:question});return;}$('#error').hidden=true;setBusy(true);try{if(!backend)throw Error('Open-ended questions need the Python backend with Ollama or Anthropic. Try one of the eight sample questions below, or open the setup guide to connect a model. You can also write your own SELECT query in the SQL tab.');if(!aiMode())throw Error('No AI provider is enabled. Open Settings → AI provider to choose Ollama or Anthropic, pick a suggested question below, or write SQL in the SQL tab.');const r=await api('ask',{question});render(r,{title:question,description:r.title||question,note:r.explanation,mode:'ai',chart:r.chart||'bar'});}catch(e){failure(e);}finally{setBusy(false);}}
function updateSaved(){$('#saved-count').textContent=saved.length;const exists=current&&saved.some(e=>e.sql===current.sql);$('#save-query').style.color=exists?'#187b66':'';$('#save-query').setAttribute('aria-label',exists?'Query saved':'Save query');}
function renderList(type){const entries=type==='saved'?saved:history;const el=$('#'+type+'-list');el.innerHTML=entries.length?entries.map((e,i)=>`<article class="query-list-card"><div><h3>${esc(e.title||e.description||'SQL query')}</h3><p>${esc(new Date(e.time).toLocaleString())} · ${esc(e.mode==='ollama'||e.mode==='ai'?'AI-generated':e.mode==='sql'?'Custom SQL':'Sample query')}${e.source_name?' · '+esc(e.source_name):''}</p></div><div><button class="secondary small" data-rerun="${i}" data-list="${type}">${icon('play')}Run again</button>${type==='saved'?`<button class="icon-button" data-remove="${i}" aria-label="Remove saved query">${icon('close')}</button>`:''}</div></article>`).join(''):`<div class="empty">${icon(type==='saved'?'bookmark':'clock')}<br>${type==='saved'?'Save an analysis with the bookmark button.':'Your next analysis will appear here.'}</div>`;el.querySelectorAll('[data-rerun]').forEach(b=>b.onclick=()=>runEntry(entries[Number(b.dataset.rerun)]));el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{const [e]=saved.splice(Number(b.dataset.remove),1);if(backend&&e.qid)await api('queries/'+e.qid,null,'DELETE').catch(()=>{});else write('saved',saved);updateSaved();renderList('saved');});}
function exportCSV(){if(!current)return;const cell=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=[current.columns,...current.rows].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='querywise-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported.');}
function schema(){if(active)return liveSchema();const tables=[['customers',80,[['id','INTEGER','PK'],['name','TEXT',''],['province','TEXT',''],['segment','TEXT','']]],['orders',720,[['id','INTEGER','PK'],['customer_id','INTEGER','FK'],['order_date','TEXT',''],['status','TEXT','']]],['products',16,[['id','INTEGER','PK'],['name','TEXT',''],['category','TEXT',''],['price','REAL','']]],['order_items',1855,[['id','INTEGER','PK'],['order_id','INTEGER','FK'],['product_id','INTEGER','FK'],['quantity','INTEGER',''],['unit_price','REAL','']]]];$('#schema-grid').innerHTML=tables.map(([name,count,fields])=>`<article class="schema-card"><header><strong>${icon('table')}${name}</strong><span class="count">${number(count)} rows</span></header>${fields.map(([name,type,key])=>`<div class="schema-field"><span>${name}${key?`<em>${key}</em>`:''}</span><span>${type}</span></div>`).join('')}</article>`).join('');}
