const STATS_SQL="SELECT ROUND(SUM(i.quantity * i.unit_price), 2) AS revenue, COUNT(DISTINCT o.id) AS completed_orders, ROUND(SUM(i.quantity * i.unit_price) / COUNT(DISTINCT o.id), 2) AS average_order_value FROM orders o JOIN order_items i ON i.order_id=o.id WHERE o.status='completed'";
function fillSampleStats(stats){if(stats.rows.length){$('#stat-revenue').textContent=money(stats.rows[0][0]);$('#stat-orders').textContent=number(stats.rows[0][1]);$('#stat-aov').textContent=money(stats.rows[0][2]);}}
function renderSuggestions(){$('#suggestions').innerHTML=catalog.map(e=>`<button class="suggestion" data-question="${esc(e.id)}">${icon(e.icon)}${esc(e.description)}</button>`).join('');$$('[data-question]').forEach(b=>b.onclick=()=>{const e=catalog.find(e=>e.id===b.dataset.question);$('#question').value=e.title;runEntry(e);});}
function updateMode(){const live='<i class="live-dot"></i> ';$('#mode-description').innerHTML=backendMode==='anthropic'?`${live}Claude AI mode <span class="muted">· ${esc(modelName||'Anthropic')}</span>`:backendMode==='ollama'?`${live}Ollama AI mode <span class="muted">· ${esc(modelName||'local model')}</span>`:`${live}Sample query mode <span class="muted">· Python backend, no model selected</span>`;$('#bottom-mode').textContent=aiMode()?'AI generates SQL from the discovered schema and your question. Inspect the query and results to verify the answer.':'Suggested questions use predefined SQL against the connected source. Choose an AI provider in Settings for open-ended questions.';$('#question').placeholder=aiMode()?`Ask anything about ${active?active.name:'your data'}…`:'e.g. Which product categories bring in the most revenue?';}
function renderSource(){const s=active,n=s.tables.length;$('#workspace-name').firstChild.textContent=s.name;$('#workspace-tag').textContent=s.id==='sample'?'DEMO':s.kind_label.toUpperCase().slice(0,10);$('#workspace-avatar').textContent=s.name.charAt(0).toUpperCase();$('#source-tile-name').firstChild.textContent=s.name;$('#source-tile-meta').innerHTML=`<i class="live-dot"></i> ${esc(s.kind_label)} · read-only`;$('#strip-name').textContent=s.name;$('#strip-desc').textContent=s.id==='sample'?'Fictional commerce dataset':s.description||`${s.dialect} · discovered ${new Date(s.discovered_at*1000).toLocaleString()}`;$('#strip-meta').innerHTML=(s.id==='sample'?['Jan–Sep 2026',`${n} tables`,'CAD currency']:[s.kind_label,`${n} ${n===1?'table':'tables'}`,'Read-only']).map(x=>`<span>${esc(x)}</span>`).join('');}
async function renderStats(){if(northstar()){$('#stats').innerHTML=sampleStats;icons();try{fillSampleStats(await executeSQL(STATS_SQL));}catch{}return;}const t=active.tables,cols=t.reduce((n,x)=>n+x.columns.length,0),fks=t.reduce((n,x)=>n+(x.foreign_keys||[]).length,0),big=[...t].sort((a,b)=>(b.row_count||0)-(a.row_count||0))[0];const stat=(label,ic,value,note)=>`<div class="stat"><div>${esc(label)} <span>${icon(ic)}</span></div><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;$('#stats').innerHTML=stat('Tables','table',number(t.length),`Discovered in ${active.kind_label}`)+stat('Columns','layers',number(cols),'Across all readable tables')+stat('Relationships','box',number(fks),fks?'Declared foreign keys':'None declared by the source')+stat('Largest table','chart',big&&big.row_count!=null?number(big.row_count):'—',big?`${big.name}${big.row_count!=null?' rows':' · row count not collected'}`:'');}
function liveSchema(){const t=active.tables;$('#schema-lead').textContent=`${t.length} ${t.length===1?'table':'tables'} discovered from ${active.name} (${active.kind_label}). The AI prompt and the table allowlist use exactly this schema.`;$('#schema-note').innerHTML=`${icon('info')} ${esc(active.definitions||'No business definitions were supplied for this source. Add them in Settings → Data sources so the AI uses your metric definitions.')}`;$('#schema-grid').innerHTML=t.map(x=>`<article class="schema-card"><header><strong>${icon('table')}${esc(x.name)}</strong><span class="count">${x.row_count!=null?number(x.row_count)+' rows':esc(x.kind||'table')}</span></header>${x.columns.map(c=>{const fk=(x.foreign_keys||[]).some(f=>f.columns.includes(c.name));return `<div class="schema-field"><span>${esc(c.name)}${c.primary_key?'<em>PK</em>':''}${fk?'<em>FK</em>':''}</span><span>${esc(c.type)}</span></div>`;}).join('')}</article>`).join('');const rel=t.flatMap(x=>(x.foreign_keys||[]).map(f=>`<p><code>${esc(f.table)}.${esc(f.references.join(', '))}</code> → <code>${esc(x.name)}.${esc(f.columns.join(', '))}</code></p>`));$('#relationships').innerHTML=`<h2>How the tables connect</h2>${rel.join('')||'<p class="muted">The source declares no foreign keys. Joins must use columns you know are related.</p>'}<p class="muted">${esc(active.controls)}${active.limits?' '+esc(active.limits):''}</p>`;}
async function refreshWorkspace(){const h=await api('health');backendMode=h.provider;modelName=h.model;if(!h.source){active=null;updateMode();$('#suggestions').innerHTML='';throw Error((h.source_error||'The active source is unavailable.')+' Open Settings → Data sources to fix it or switch back to the Northstar sample.');}const s=await api('schema');active={...h.source,tables:s.tables,definitions:s.definitions,controls:s.controls,limits:s.limits,description:s.description};catalog=await api('catalog');updateMode();renderSource();renderSuggestions();schema();await renderStats();$('#error').hidden=true;if(catalog.length){const r=await executeSQL(catalog[0].sql);render(r,catalog[0],false);}else{$('#result').hidden=true;}}
async function addEntry(list,entry){const e={...entry,rows:undefined,columns:undefined,qid:undefined,source:active?.id,source_name:active?.name};const arr=list==='saved'?saved:history,max=list==='saved'?50:40;if(backend){try{const r=await api('queries',{list,entry:e});arr.unshift({...e,qid:r.id});arr.splice(max);return;}catch{}}arr.unshift(e);arr.splice(max);write(list,arr);}
async function loadLists(){try{const fromServer=async list=>(await api('queries?list='+list)).map(e=>({...e,qid:e.id,id:e.entry_id}));let migrated=false;try{migrated=localStorage.getItem('querywise:migrated')==='1';}catch{}if(!migrated){for(const list of ['history','saved'])for(const e of [...read(list)].reverse())await api('queries',{list,entry:{...e,rows:undefined,columns:undefined}}).catch(()=>{});try{localStorage.setItem('querywise:migrated','1');}catch{}}history=await fromServer('history');saved=await fromServer('saved');updateSaved();}catch{/* Older backend or unavailable: keep localStorage lists. */}}
// Settings: data sources and AI provider. Secrets are write-only; the API returns masks.
const FIELD_KINDS={url:k=>sources.kinds[k].target==='url',url_env:k=>sources.kinds[k].target==='url',path:k=>sources.kinds[k].target==='path',path_env:k=>sources.kinds[k].target==='path',username:k=>sources.kinds[k].target==='url',password:k=>sources.kinds[k].target==='url',api_key:k=>k==='elasticsearch',ca_cert:k=>k==='elasticsearch',verify_tls:k=>k==='elasticsearch',schema:k=>['postgres','sqlserver','oracle','db2'].includes(k),database:k=>k==='mongodb'};
function status(id,msg,ok){const el=$('#'+id);el.textContent=msg;el.className='form-status '+(ok===true?'ok':ok===false?'bad':'');el.hidden=!msg;}
async function openSettings(tab){if(!backend){toast('Settings need the Python backend. Open the setup guide to run it locally.');setup();return;}settingsTab(tab);$('#settings-dialog').showModal();await Promise.all([loadSources().catch(e=>status('sources-status',e.message,false)),loadAI().catch(e=>status('ai-status',e.message,false))]);}
function settingsTab(name){$$('[data-settings-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.settingsTab===name);b.setAttribute('aria-selected',String(b.dataset.settingsTab===name));});$('#settings-sources').hidden=name!=='sources';$('#settings-ai').hidden=name!=='ai';}
async function loadSources(){const d=await api('sources');sources={list:d.sources,kinds:d.kinds};$('#source-kind').innerHTML=Object.entries(d.kinds).map(([k,v])=>`<option value="${k}">${esc(v.label)}</option>`).join('');renderSources();}
function renderSources(){const origin={builtin:'Built-in',env:'Environment',file:'Sources file',stored:'Saved'};$('#source-list').innerHTML=sources.list.map(s=>{const u=s.secrets.url,where=s.config.path||s.config.path_env&&('$'+s.config.path_env)||(u.env?'$'+u.env+(u.from_env?'':' (not set)'):u.set?`${s.scheme||'url'} ${u.masked}`:'');return `<article class="source-item${s.active?' active':''}"><div class="source-main"><span class="source-icon">${icon('database')}</span><div><strong>${esc(s.name)}</strong><small>${esc(s.kind_label)} · ${esc(origin[s.origin]||s.origin)}${where?' · <code>'+esc(where)+'</code>':''}</small>${s.error?`<small class="bad">${esc(s.error)}</small>`:''}</div>${s.active?'<span class="pill">ACTIVE</span>':''}</div><div class="source-actions">${s.active?`<button class="secondary small" data-src="refresh" data-id="${esc(s.id)}">${icon('refresh')}Rediscover</button>`:`<button class="primary small" data-src="select" data-id="${esc(s.id)}">${icon('plug')}Connect</button>`}<button class="secondary small" data-src="test" data-id="${esc(s.id)}">Test</button>${s.editable?`<button class="icon-button" data-src="edit" data-id="${esc(s.id)}" aria-label="Edit ${esc(s.name)}">${icon('edit')}</button><button class="icon-button" data-src="remove" data-id="${esc(s.id)}" aria-label="Remove ${esc(s.name)}">${icon('trash')}</button>`:''}</div></article>`;}).join('');$$('[data-src]').forEach(b=>b.onclick=()=>sourceAction(b.dataset.src,b.dataset.id,b));}
async function sourceAction(action,id,button){const s=sources.list.find(x=>x.id===id);if(action==='edit')return showSourceForm(s);if(action==='remove'){if(!confirm(`Remove “${s.name}” and its saved credentials?`))return;await api('sources/'+encodeURIComponent(id),null,'DELETE').catch(e=>status('sources-status',e.message,false));await loadSources();if(s.active)await refreshWorkspace().catch(failure);return;}button.disabled=true;status('sources-status',action==='test'?`Testing ${s.name}…`:`Testing the connection to ${s.name}, then discovering its schema…`);try{if(action==='test'){const r=await api(`sources/${encodeURIComponent(id)}/test`,{});status('sources-status',`✓ ${r.message} (${r.elapsed_ms} ms)`,true);}else{const r=await api(action==='refresh'?'sources/refresh':`sources/${encodeURIComponent(id)}/select`,{});status('sources-status',`✓ Connected to ${r.source.name}: ${r.source.tables} tables discovered.`,true);await loadSources();await refreshWorkspace();toast(`Switched to ${r.source.name}.`);}}catch(e){status('sources-status',e.message,false);}finally{button.disabled=false;}}
function showSourceForm(src){editing=src||null;const f=$('#source-form');f.reset();f.hidden=false;$('#add-source').hidden=true;$('#source-form-title').textContent=src?`Edit ${src.name}`:'Add a connection';f.elements.kind.disabled=!!src;if(src){const c=src.config;f.elements.name.value=src.name;f.elements.kind.value=src.kind;for(const k of ['path','path_env','url_env','username','schema','database','definitions','ca_cert'])f.elements[k].value=c[k]||'';f.elements.tables.value=(c.tables||[]).join(', ');f.elements.verify_tls.checked=c.verify_tls!==false;}for(const k of ['url','password','api_key']){const sec=src?.secrets[k];f.elements[k].placeholder=sec?.set&&!sec.from_env?`Saved ${sec.masked} — leave blank to keep`:k==='api_key'?'Elasticsearch API key':'';}kindChanged();status('source-status','');f.elements.name.focus();}
function kindChanged(){const f=$('#source-form'),k=f.elements.kind.value,info=sources.kinds[k];if(!info)return;$$('#source-form [data-field]').forEach(el=>el.hidden=!(FIELD_KINDS[el.dataset.field]||(()=>true))(k));if(!editing||!editing.secrets.url.set)f.elements.url.placeholder=info.example;if(!editing)f.elements.path.placeholder=info.example;$('#kind-hint').innerHTML=`<strong>Read-only controls:</strong> ${esc(info.controls)}${info.limits?`<br><strong>Limits:</strong> ${esc(info.limits)}`:''}`;}
function formBody(){const f=$('#source-form'),v=n=>f.elements[n].value.trim(),k=f.elements.kind.value,b={name:v('name'),kind:k},shown=n=>!f.elements[n].closest('[data-field]')?.hidden;for(const n of ['url_env','path','path_env','username','schema','database','definitions','ca_cert'])if(shown(n)&&(v(n)||editing))b[n]=v(n);for(const n of ['url','password','api_key'])if(shown(n)&&v(n))b[n]=v(n);const t=v('tables');if(t||editing)b.tables=t?t.split(',').map(x=>x.trim()).filter(Boolean):[];if(k==='elasticsearch')b.verify_tls=f.elements.verify_tls.checked;return b;}
async function submitSource(connect){const f=$('#source-form');if(!f.reportValidity())return;const b=formBody();status('source-status',connect?'Saving, testing the connection, then discovering the schema…':'Saving…');try{const s=editing?await api('sources/'+encodeURIComponent(editing.id),b,'PUT'):await api('sources',b);if(connect){const r=await api(`sources/${encodeURIComponent(s.id)}/select`,{});await refreshWorkspace();toast(`Switched to ${r.source.name}: ${r.source.tables} tables.`);}f.hidden=true;$('#add-source').hidden=false;editing=null;await loadSources();status('sources-status',connect?`✓ Connected to ${s.name}.`:`✓ Saved ${s.name}. Secrets are encrypted locally and shown only as masks.`,true);}catch(e){status('source-status',e.message,false);await loadSources().catch(()=>{});}}
async function testForm(){const f=$('#source-form');if(!f.reportValidity())return;if(editing){status('source-status','Testing the saved connection (save first to test edited values)…');try{const r=await api(`sources/${encodeURIComponent(editing.id)}/test`,{});status('source-status',`✓ ${r.message} (${r.elapsed_ms} ms)`,true);}catch(e){status('source-status',e.message,false);}return;}status('source-status','Testing the connection…');try{const r=await api('sources/test',formBody());status('source-status',`✓ ${r.message} (${r.elapsed_ms} ms). Save it to use it.`,true);}catch(e){status('source-status',e.message,false);}}
let aiSettings=null;
async function loadAI(){const d=await api('settings'),s=d.settings,f=$('#ai-form');aiSettings=s;f.elements.provider.value=s.provider.value;f.elements.anthropic_model.value=s.anthropic_model.value;f.elements.anthropic_effort.value=s.anthropic_effort.value;f.elements.anthropic_workspace_id.value=s.anthropic_workspace_id.value;f.elements.ollama_url.value=s.ollama_url.value;f.elements.ollama_model.value=s.ollama_model.value;f.elements.anthropic_api_key.value='';const k=s.anthropic_api_key;f.elements.anthropic_api_key.placeholder=k.set?`${k.origin==='env'?'From ANTHROPIC_API_KEY':'Saved key'} ${k.masked}${k.origin==='env'?'':' — leave blank to keep'}`:'sk-ant-…';$('#clear-key').hidden=!(k.set&&k.origin==='stored');for(const [name,v] of Object.entries(s)){const el=f.elements[name];if(!el)continue;el.disabled=v.locked;const note=$(`[data-lock="${name}"]`);if(note)note.textContent=v.locked?`Set by ${v.env}`:'';}if(k.origin==='unreadable')status('ai-status','The saved API key cannot be decrypted with the current secret key. Paste it again.',false);aiProvider();}
function aiProvider(){const p=$('#ai-form').elements.provider.value;$('#anthropic-fields').hidden=p!=='anthropic';$('#ollama-fields').hidden=p!=='ollama';}
async function saveAI(e){e?.preventDefault();const f=$('#ai-form'),b={};for(const n of ['provider','anthropic_model','anthropic_effort','anthropic_workspace_id','ollama_url','ollama_model'])if(!f.elements[n].disabled&&f.elements[n].value.trim()&&f.elements[n].value.trim()!==aiSettings[n].value)b[n]=f.elements[n].value.trim();if(!f.elements.anthropic_workspace_id.disabled&&!f.elements.anthropic_workspace_id.value.trim()&&aiSettings.anthropic_workspace_id.origin==='stored')b.clear=['anthropic_workspace_id'];if(f.elements.anthropic_api_key.value.trim()&&!f.elements.anthropic_api_key.disabled)b.anthropic_api_key=f.elements.anthropic_api_key.value.trim();status('ai-status','Saving…');try{await api('settings',b,'PUT');await loadAI();const h=await api('health');backendMode=h.provider;modelName=h.model;updateMode();const k=aiSettings.anthropic_api_key;status('ai-status',`✓ Saved.${k.set?` Your API key (${k.masked}) is stored encrypted; the field stays empty because saved keys are never sent back to the browser.`:''}`,true);return true;}catch(err){status('ai-status',err.message,false);return false;}}
async function checkAI(){if(!await saveAI())return;status('ai-status','Checking the provider…');try{status('ai-status','✓ '+(await api('settings/check',{})).message,true);}catch(e){status('ai-status',e.message,false);}}
icons();syncTheme(false);$('#theme-toggle').onclick=toggleTheme;darkQuery.addEventListener('change',()=>{if(!document.documentElement.dataset.theme)syncTheme(true);});schema();updateSaved();$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$$('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();view('explore');};$('#ask-form').onsubmit=e=>{e.preventDefault();ask($('#question').value);};$('#question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask(e.target.value);}};$('#new-query').onclick=()=>{$('#question').value='';$('#error').hidden=true;$('#question').focus();};$('#run-sql').onclick=()=>runEntry({title:'Custom SQL query',description:'Custom SQL analysis',sql:$('#sql-editor').value,mode:'sql',chart:'bar',note:'Custom SELECT executed read-only. Results are capped at 500 rows.'});$('#save-query').onclick=async()=>{if(!current)return;if(saved.some(e=>e.sql===current.sql)){toast('This query is already saved.');return;}await addEntry('saved',current);updateSaved();toast('Query saved to your collection.');};$('#export').onclick=exportCSV;$('#copy-sql').onclick=async()=>{try{await navigator.clipboard.writeText($('#sql-editor').value);toast('SQL copied.');}catch{toast('Select and copy the SQL from the editor.');}};$('#clear-history').onclick=async()=>{if(backend)await api('queries?list=history',null,'DELETE').catch(()=>{});history=[];write('history',[]);renderList('history');toast('Query history cleared.');};['setup-link','help','bottom-setup'].forEach(id=>$('#'+id).onclick=setup);['settings','header-settings','source-tile','switch-source'].forEach(id=>$('#'+id).onclick=()=>openSettings(id==='settings'?'ai':'sources'));$('#close-dialog').onclick=()=>$('#setup-dialog').close();$('#chart').addEventListener('mousemove',chartHover);let chartResize;window.addEventListener('resize',()=>{clearTimeout(chartResize);chartResize=setTimeout(()=>{if(current&&current.columns&&!$('#chart-panel').hidden)renderChart(current,current,true);},150);});$('#chart').addEventListener('mouseleave',chartHover);$('#close-settings').onclick=()=>$('#settings-dialog').close();$$('[data-settings-tab]').forEach(b=>b.onclick=()=>settingsTab(b.dataset.settingsTab));$('#add-source').onclick=()=>showSourceForm();$('#cancel-source').onclick=()=>{$('#source-form').hidden=true;$('#add-source').hidden=false;editing=null;};$('#source-kind').onchange=kindChanged;$('#test-source').onclick=testForm;$('#save-source').onclick=()=>submitSource(false);$('#source-form').onsubmit=e=>{e.preventDefault();submitSource(true);};$('#ai-form').onsubmit=saveAI;$('#ai-provider').onchange=aiProvider;$('#check-ai').onclick=checkAI;$('#clear-key').onclick=async()=>{try{await api('settings',{clear:['anthropic_api_key']},'PUT');await loadAI();status('ai-status','Saved key removed.',true);}catch(e){status('ai-status',e.message,false);}};$('#setup-dialog').onclick=e=>{if(e.target===$('#setup-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
async function init(){sampleStats=$('#stats').innerHTML;try{catalog=await fetch('catalog.json').then(r=>r.json());try{const r=await fetch('/api/health',{signal:AbortSignal.timeout(1500)});if(r.ok&&(r.headers.get('content-type')||'').includes('application/json')){const h=await r.json();backend=h.app==='querywise';backendMode=h.provider;}}catch{}
 if(backend){await loadLists();await refreshWorkspace();return;}
 renderSuggestions();const stats=await executeSQL(STATS_SQL);fillSampleStats(stats);const result=await executeSQL(catalog[0].sql);render(result,catalog[0],false);
 }catch(e){failure(e);$('#summary').textContent='The database could not initialize. Reload this page or check the active source in Settings.';}}
